type User = { role: "member" | "admin" } | null;
type RouteMeta = { requiresAuth: boolean; adminOnly?: boolean };

function canAccessRoute(route: RouteMeta, user: User): boolean {
  if (!route.requiresAuth) {
    return true;
  }
  if (user === null) {
    return false;
  }
  if (route.adminOnly === true) {
    return user.role === "admin";
  }
  return true;
}

function routeRedirect(route: RouteMeta, user: User): string | null {
  if (canAccessRoute(route, user)) {
    return null;
  }
  return user === null ? "/login" : "/catalog";
}
